// Before `tauri android build`: makes the generated app/build.gradle.kts sign
// release APKs with the key named in gen/android/keystore.properties. The Gradle
// file is generated by `tauri android init`, so the change is applied here rather
// than edited by hand. Also repairs a hand-edited file. Safe to run again.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const gradleFile = fileURLToPath(new URL('../src-tauri/gen/android/app/build.gradle.kts', import.meta.url));
const keystoreProps = fileURLToPath(new URL('../src-tauri/gen/android/keystore.properties', import.meta.url));

function fail(message) {
	console.error(message);
	process.exit(1);
}

if (!existsSync(gradleFile)) fail(`Not found: ${gradleFile}\nRun \`npm run android:init\` first.`);
if (!existsSync(keystoreProps)) fail(`Not found: ${keystoreProps}\nCreate the signing key and this file first: see BUILD.md, section 3.4.`);

// Gradle looks this block up as soon as it reads buildTypes, so it has to come first.
const SIGNING_BLOCK = `    signingConfigs {
        val keystoreProps = rootProject.file("keystore.properties")
        if (keystoreProps.exists()) {
            create("release") {
                val props = Properties().apply { keystoreProps.inputStream().use { load(it) } }
                keyAlias = props["keyAlias"] as String
                keyPassword = props["password"] as String
                storeFile = file(props["storeFile"] as String)
                storePassword = props["password"] as String
            }
        }
    }
`;
const SIGNING_LINE = '            signingConfig = signingConfigs.findByName("release")\n';

// Removes the block that `opener` matches, through the end of its closing line.
function removeBlock(text, opener) {
	const match = opener.exec(text);
	if (!match) return text;
	let depth = 0;
	for (let i = match.index + match[0].length - 1; i < text.length; i++) {
		if (text[i] === '{') depth++;
		if (text[i] === '}' && --depth === 0) {
			const newline = text.indexOf('\n', i);
			return text.slice(0, match.index) + text.slice(newline === -1 ? text.length : newline + 1);
		}
	}
	fail(`Unbalanced braces in ${gradleFile}`);
}

const original = readFileSync(gradleFile, 'utf8');

// Start from a clean file, so this also corrects a block in the wrong place.
let text = removeBlock(original, /^[ \t]*signingConfigs\s*\{/m);
text = text.replace(/^[ \t]*signingConfig\s*=.*\r?\n/gm, '');

const buildTypes = /^[ \t]*buildTypes\s*\{/m;
const release = /getByName\("release"\)\s*\{\r?\n/;
if (!buildTypes.test(text) || !release.test(text)) {
	fail(`${gradleFile} has an unexpected layout: no buildTypes or release block. See BUILD.md, section 3.4.`);
}

text = text.replace(buildTypes, (m) => SIGNING_BLOCK + m);
text = text.replace(release, (m) => m + SIGNING_LINE);
if (!/^import java\.util\.Properties\s*$/m.test(text)) text = `import java.util.Properties\n${text}`;

if (text === original) {
	console.log('build.gradle.kts already has release signing.');
} else {
	writeFileSync(gradleFile, text);
	console.log('Added release signing to build.gradle.kts.');
}
